node -e '
const fs=require("fs");
let s=fs.readFileSync(process.env.TEMP+"/b7008-captcha-uri.txt","utf8").trim();
let m=s.match(/data:image\/[^;]+;base64,([A-Za-z0-9+/=]+)/);
if(!m){console.log("NO MATCH, head:",s.slice(0,200));process.exit(1);}
fs.writeFileSync(process.env.TEMP+"/bug7008-captcha-20261126-1658.png",Buffer.from(m[1],"base64"));
console.log("WROTE captcha png",m[1].length,"b64chars");
'
